typedef float rational_t;

class vector3d
{
public:
  rational_t x, y, z;
  inline vector3d(rational_t _x, rational_t _y, rational_t _z) { x = _x; y = _y; z = _z; }
};

class region_node;

class entity
{
public:
  void remove_from_terrain();
  virtual void force_region(region_node* r);
  virtual void set_active(bool a);
  void set_rel_position(const vector3d& p);
};

class world_dynamics_system
{
public:
  void remove_entity_from_world_processing(entity* e);
};

void world_dynamics_system::remove_entity_from_world_processing( entity *e )
{
  e->remove_from_terrain();
  e->force_region( 0 );  // this effectively removes the entity from the world
  e->set_active( false );
  e->set_rel_position( vector3d(-9000.0f,-9000.0f,-9000.0f) );
}
